<main class="main" id="assign-subjects"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb" aria-label="Breadcrumb"><a href="<?= url('/admin/dashboard') ?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Subjects</span><i data-lucide="chevron-right"></i><span aria-current="page">Assign Subjects</span></nav><h1>Assign Subjects</h1><p>Add a subject and total marks to a selected class</p></div></header><form class="module-card" method="post" action="<?= url('/admin/subjects') ?>"><?= csrf_field() ?><header class="module-card__header"><div><h2>Assign Subject to Class</h2><p>Choose a class, then define the subject name and total marks.</p></div></header><div class="module-card__body"><div class="module-form-grid module-form-grid--three"><div class="module-field"><label for="subject_class">Select Class <span class="required">*</span></label><select class="module-select" id="subject_class" name="subject_class" required <?= !$classes?'disabled':'' ?>><option value="">Select class</option><?php foreach($classes as $class):?><option value="<?= e($class['id']) ?>" <?= (string)old('subject_class')===(string)$class['id']?'selected':'' ?>><?= e($class['name']) ?></option><?php endforeach ?></select></div><div class="module-field"><label for="subject_name">Subject Name <span class="required">*</span></label><input class="module-input" id="subject_name" name="subject_name" type="text" value="<?= e(old('subject_name')) ?>" required></div><div class="module-field"><label for="subject_marks">Marks <span class="required">*</span></label><input class="module-input" id="subject_marks" name="subject_marks" type="number" value="<?= e(old('subject_marks')) ?>" min="1" step="0.01" required></div></div><?php if(!$classes):?><div class="notice-panel" style="margin-top:18px"><i data-lucide="info"></i><span>No classes are available. Create a class first.</span></div><?php endif ?></div><footer class="module-card__footer"><button class="btn btn--primary" type="submit" <?= !$classes?'disabled':'' ?>>Assign Subject</button></footer></form></div></div></main>
